-- Example special workspace (scratchpad)

--bind = $mainMod, W, togglespecialworkspace, magic

--bind = $mainMod SHIFT, S, movetoworkspace, special:magic

-- Scroll through existing workspaces with mainMod + scroll

hl.bind(mainMod .. " + " .. "mouse_down", hl.dsp.focus({ workspace = "e+1" }))

hl.bind(mainMod .. " + " .. "mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging

hl.bind(mainMod .. " + " .. "mouse:272", hl.dsp.window.drag(), { mouse = true })

hl.bind(mainMod .. " + " .. "mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Screenshotting

hl.bind("Print", hl.dsp.exec_cmd("hyprshot -m active -m output"))

-- screenshot active screen

hl.bind(mainMod .. " + " .. "Print", hl.dsp.exec_cmd("notify-send -t 1000 \"Entering screenshot mode (ESC to exit)\""))

hl.bind(mainMod .. " + " .. "Print", hl.dsp.submap("screenshot"))

hl.define_submap("screenshot", function()
    -- screenshot active screen and pipe into satty for editing 
    hl.bind("e", hl.dsp.exec_cmd("hyprshot -m active -m output --raw | satty -f -"))
    hl.bind("e", hl.dsp.submap("reset"))
    -- screenshot a window
    hl.bind("w", hl.dsp.exec_cmd("hyprshot -m window --freeze"))
    hl.bind("w", hl.dsp.submap("reset"))
    -- screenshot a window and pipe into satty for editing
    hl.bind("Shift + w", hl.dsp.exec_cmd("hyprshot -m window --freeze --raw | satty -f -"))
    hl.bind("Shift + w", hl.dsp.submap("reset"))
    -- screenshot a region
    hl.bind("r", hl.dsp.exec_cmd("hyprshot -m region --freeze"))
    hl.bind("r", hl.dsp.submap("reset"))
    -- screenshot a region and pipe into satty for editing
    hl.bind("Shift + r", hl.dsp.exec_cmd("hyprshot -m region --freeze --raw | satty -f -"))
    hl.bind("Shift + r", hl.dsp.submap("reset"))
    hl.bind("escape", hl.dsp.submap("reset"))
end)


