-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more

-- See https://wiki.hyprland.org/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrule v1

-- windowrule = float, ^(kitty)$

-- Example windowrule v2

-- windowrulev2 = float,class:^(kitty)$,title:^(kitty)$

hl.window_rule({
    name  = "windowrule-1",
    match = {
        title = "^Picture-in-Picture$",
    },
    pin = true,
    float = true,
})

hl.window_rule({
    name  = "windowrule-2",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "windowrule-3",
    match = {
        fullscreen = 1,
    },
    border_color = "rgb(1E4A28) rgb(0F2514)",
})

hl.window_rule({
    name  = "windowrule-4",
    match = {
        class = "(firefox)",
    },
    sync_fullscreen = 0,
})

hl.window_rule({
    name  = "windowrule-5",
    match = {
        class = "(zen)",
    },
    sync_fullscreen = 0,
})

hl.window_rule({
    name  = "windowrule-6",
    match = {
        class = "(Jellyfin Media Player)",
    },
    tile = true,
})

hl.window_rule({
    name  = "windowrule-7",
    match = {
        class = "(emote)",
    },
    move = { "(cursor_x+(min(max((monitor_w*0),0),monitor_w-window_w)))", "(cursor_y+(min(max((monitor_h*0),0),monitor_h-window_h)))" },
})

hl.window_rule({
    name  = "windowrule-8",
    match = {
        class = "^(xwaylandvideobridge)$",
    },
    opacity = { 0.0, "override" },
    no_anim = true,
    no_initial_focus = true,
    max_size = "1 1",
    no_blur = true,
})

hl.window_rule({
    name  = "windowrule-9",
    match = {
        class = "(Emulator)",
    },
    float = true,
})

hl.layer_rule({
    match = {
        namespace = "wofi",
    },
    ignore_alpha = 0,
})

hl.window_rule({
    name  = "workspace_4_371",
    match = {
        class = "spotify",
    },
    workspace = 4,
})

hl.window_rule({
    name  = "workspace_5_372",
    match = {
        class = "vesktop",
    },
    workspace = 5,
})

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("dunst &")
    hl.exec_cmd("waybar &")
    hl.exec_cmd("udiskie &")
    hl.exec_cmd("emote")
    hl.exec_cmd("blueman-applet &")
    hl.exec_cmd("nm-applet &")
    hl.exec_cmd("sleep 8; nextcloud &")
    hl.exec_cmd("awww-daemon &")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("shikane > ~/.config/shikane/shikane.log")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("[workspace 4 silent] spotify-launcher")
    hl.exec_cmd("[workspace 5 silent] vesktop")
    hl.exec_cmd("[workspace 2 silent] zen-browser")
end)
